  INSERT INTO class_subjects (class_id, subject_id) VALUES (c10_id, soc_id) ON CONFLICT DO NOTHING;
  INSERT INTO questions (school_id, subject_id, question_type, question_text, options, answer, marks, difficulty, chapters, tags, is_active) VALUES
  (sid, soc_id, 'mcq', 'The ''Gateway of European'' trade in the Middle Ages was', '[{"key": "A", "value": "Rome", "correct": false}, {"key": "B", "value": "Constantinople", "correct": true}, {"key": "C", "value": "Paris", "correct": false}, {"key": "D", "value": "Venice", "correct": false}]', 'B', 1, 'medium', '["THE ADVENT OF EUROPEANS TO INDIA"]', '["history", "europeans", "trade"]', true),
  (sid, soc_id, 'mcq', 'The Portuguese sailor who discovered a new sea route to India in 1498 was', '[{"key": "A", "value": "Vasco da Gama", "correct": true}, {"key": "B", "value": "Dupleix", "correct": false}, {"key": "C", "value": "Francisco de Almeida", "correct": false}, {"key": "D", "value": "Alfonso de Albuquerque", "correct": false}]', 'A', 1, 'easy', '["THE ADVENT OF EUROPEANS TO INDIA"]', '["history", "voyages", "discovery"]', true),
  (sid, soc_id, 'mcq', 'The Portuguese Viceroy who implemented the ''Blue Water Policy'' was', '[{"key": "A", "value": "Vasco da Gama", "correct": false}, {"key": "B", "value": "Francisco de Almeida", "correct": true}, {"key": "C", "value": "Alfonso de Albuquerque", "correct": false}, {"key": "D", "value": "Dupleix", "correct": false}]', 'B', 1, 'hard', '["THE ADVENT OF EUROPEANS TO INDIA"]', '["history", "portuguese", "policy"]', true),
  (sid, soc_id, 'mcq', 'The First Carnatic War ended with the treaty of', '[{"key": "A", "value": "Pondicherry", "correct": false}, {"key": "B", "value": "Aix-la-Chapelle", "correct": true}, {"key": "C", "value": "Paris", "correct": false}, {"key": "D", "value": "Wandiwash", "correct": false}]', 'B', 1, 'hard', '["THE ADVENT OF EUROPEANS TO INDIA"]', '["history", "carnatic_wars", "treaties"]', true),
  (sid, soc_id, 'mcq', 'The Mughal emperor who gave permission to the British to trade freely in Bengal was', '[{"key": "A", "value": "Jahangir", "correct": false}, {"key": "B", "value": "Shah Alam II", "correct": false}, {"key": "C", "value": "Bahadur Shah", "correct": false}, {"key": "D", "value": "Farooq Siyar", "correct": true}]', 'D', 1, 'medium', '["THE ADVENT OF EUROPEANS TO INDIA"]', '["history", "mughals", "trade"]', true),
  (sid, soc_id, 'mcq', 'The First Anglo-Maratha War ended with the treaty of', '[{"key": "A", "value": "Bassein", "correct": false}, {"key": "B", "value": "Salbai", "correct": true}, {"key": "C", "value": "Lahore", "correct": false}, {"key": "D", "value": "Poona", "correct": false}]', 'B', 1, 'medium', '["THE EXTENSION OF THE BRITISH RULE"]', '["history", "marathas", "treaties"]', true),
  (sid, soc_id, 'mcq', 'The system of Subsidiary Alliance was introduced in India by', '[{"key": "A", "value": "Dalhousie", "correct": false}, {"key": "B", "value": "Wellesley", "correct": true}, {"key": "C", "value": "William Bentinck", "correct": false}, {"key": "D", "value": "Cornwallis", "correct": false}]', 'B', 1, 'easy', '["THE EXTENSION OF THE BRITISH RULE"]', '["history", "british_expansion", "policies"]', true),
  (sid, soc_id, 'mcq', 'The first princely state which accepted the system of Subsidiary Alliance was', '[{"key": "A", "value": "Hyderabad", "correct": true}, {"key": "B", "value": "Mysore", "correct": false}, {"key": "C", "value": "Maratha", "correct": false}, {"key": "D", "value": "Punjab", "correct": false}]', 'A', 1, 'easy', '["THE EXTENSION OF THE BRITISH RULE"]', '["history", "subsidiary_alliance", "princely_states"]', true),
  (sid, soc_id, 'mcq', 'After the 3rd Anglo-Maratha War, the traditional leader installed by the British in Satara was', '[{"key": "A", "value": "Sambhaji", "correct": false}, {"key": "B", "value": "Shivaji", "correct": false}, {"key": "C", "value": "Shahaji", "correct": false}, {"key": "D", "value": "Pratap Simha", "correct": true}]', 'D', 1, 'hard', '["THE EXTENSION OF THE BRITISH RULE"]', '["history", "marathas", "rulers"]', true),
  (sid, soc_id, 'mcq', 'The Governor General who implemented the ''Doctrine of Lapse'' was', '[{"key": "A", "value": "Dalhousie", "correct": true}, {"key": "B", "value": "Wellesley", "correct": false}, {"key": "C", "value": "William Bentinck", "correct": false}, {"key": "D", "value": "Cornwallis", "correct": false}]', 'A', 1, 'easy', '["THE EXTENSION OF THE BRITISH RULE"]', '["history", "doctrine_of_lapse", "policies"]', true),
  (sid, soc_id, 'mcq', 'The Governor General who annexed Punjab to the British Empire was', '[{"key": "A", "value": "Dalhousie", "correct": true}, {"key": "B", "value": "Wellesley", "correct": false}, {"key": "C", "value": "Canning", "correct": false}, {"key": "D", "value": "Cornwallis", "correct": false}]', 'A', 1, 'medium', '["THE EXTENSION OF THE BRITISH RULE"]', '["history", "sikh_wars", "punjab"]', true),
  (sid, soc_id, 'mcq', 'The law which made provision for the establishment of the Supreme Court in Calcutta was', '[{"key": "A", "value": "Regulating Act of 1773", "correct": true}, {"key": "B", "value": "Charter Act of 1833", "correct": false}, {"key": "C", "value": "Government of India Act of 1935", "correct": false}, {"key": "D", "value": "Indian Council Act of 1909", "correct": false}]', 'A', 1, 'medium', '["THE IMPACT OF THE BRITISH RULE IN INDIA"]', '["history", "administration", "acts"]', true),
  (sid, soc_id, 'mcq', 'The post of Superintendent of Police in India was created by', '[{"key": "A", "value": "Warren Hastings", "correct": false}, {"key": "B", "value": "Cornwallis", "correct": true}, {"key": "C", "value": "Wellesley", "correct": false}, {"key": "D", "value": "Dalhousie", "correct": false}]', 'B', 1, 'easy', '["THE IMPACT OF THE BRITISH RULE IN INDIA"]', '["history", "administration", "police"]', true),
  (sid, soc_id, 'mcq', 'The British Governor who established new universities in Calcutta, Bombay, and Madras was', '[{"key": "A", "value": "William Bentinck", "correct": false}, {"key": "B", "value": "Warren Hastings", "correct": false}, {"key": "C", "value": "Dalhousie", "correct": true}, {"key": "D", "value": "Thomas Munroe", "correct": false}]', 'C', 1, 'hard', '["THE IMPACT OF THE BRITISH RULE IN INDIA"]', '["history", "education", "universities"]', true),
  (sid, soc_id, 'mcq', 'The Act which provided separate electoral colleges for Muslims in India was', '[{"key": "A", "value": "Indian Council Act of 1909", "correct": true}, {"key": "B", "value": "Government of India Act of 1919", "correct": false}, {"key": "C", "value": "Government of India Act of 1935", "correct": false}, {"key": "D", "value": "Indian Council Act of 1892", "correct": false}]', 'A', 1, 'hard', '["THE IMPACT OF THE BRITISH RULE IN INDIA"]', '["history", "administration", "acts"]', true),
  (sid, soc_id, 'mcq', 'The Government of India Act of 1935 is considered an important document for independent India because', '[{"key": "A", "value": "It introduced Diarchy at provinces", "correct": false}, {"key": "B", "value": "It established a Board of Control", "correct": false}, {"key": "C", "value": "It introduced separate electoral constituencies on the basis of caste", "correct": false}, {"key": "D", "value": "It created a Federal System", "correct": true}]', 'D', 1, 'medium', '["THE IMPACT OF THE BRITISH RULE IN INDIA"]', '["history", "administration", "acts"]', true),
  (sid, soc_id, 'mcq', 'The permanent Zamindari system of land revenue was introduced by', '[{"key": "A", "value": "Warren Hastings", "correct": false}, {"key": "B", "value": "Cornwallis", "correct": true}, {"key": "C", "value": "Wellesley", "correct": false}, {"key": "D", "value": "Dalhousie", "correct": false}]', 'B', 1, 'easy', '["THE IMPACT OF THE BRITISH RULE IN INDIA"]', '["history", "land_revenue", "zamindari"]', true),
  (sid, soc_id, 'mcq', 'The report that became the base for English education in India was made by', '[{"key": "A", "value": "Alexander Reed", "correct": false}, {"key": "B", "value": "Macaulay", "correct": true}, {"key": "C", "value": "Charles Wood", "correct": false}, {"key": "D", "value": "Peel", "correct": false}]', 'B', 1, 'hard', '["THE IMPACT OF THE BRITISH RULE IN INDIA"]', '["history", "education", "english"]', true),
  (sid, soc_id, 'mcq', 'The state anthem of Mysore, ''Kayo Sri Gowri'', was composed by', '[{"key": "A", "value": "Sanchi Honnamma", "correct": false}, {"key": "B", "value": "Shyama Shastri", "correct": false}, {"key": "C", "value": "Basappa Shastri", "correct": true}, {"key": "D", "value": "Thirumalarya", "correct": false}]', 'C', 1, 'medium', '["OPPOSITION TO BRITISH RULE IN KARNATAKA AND WODEYARS OF MYSORE"]', '["history", "karnataka", "mysore"]', true),
  (sid, soc_id, 'mcq', 'The Treaty that ended the First Anglo-Mysore War was', '[{"key": "A", "value": "Treaty of Mangalore", "correct": false}, {"key": "B", "value": "Treaty of Srirangapattana", "correct": false}, {"key": "C", "value": "Salbai Agreement", "correct": false}, {"key": "D", "value": "Treaty of Madras", "correct": true}]', 'D', 1, 'easy', '["OPPOSITION TO BRITISH RULE IN KARNATAKA AND WODEYARS OF MYSORE"]', '["history", "karnataka", "mysore_wars"]', true),
  (sid, soc_id, 'mcq', 'Surapura (historical site of rebellion) is located in the present-day district of', '[{"key": "A", "value": "Kalaburagi", "correct": false}, {"key": "B", "value": "Bellary", "correct": false}, {"key": "C", "value": "Raichur", "correct": false}, {"key": "D", "value": "Yadagir", "correct": true}]', 'D', 1, 'medium', '["OPPOSITION TO BRITISH RULE IN KARNATAKA AND WODEYARS OF MYSORE"]', '["history", "karnataka", "surapura"]', true),
  (sid, soc_id, 'mcq', 'The place where Sangolli Rayanna was hanged to death by the British was', '[{"key": "A", "value": "Kittur", "correct": false}, {"key": "B", "value": "Nandagadh", "correct": true}, {"key": "C", "value": "Belagavi", "correct": false}, {"key": "D", "value": "Sampagavi", "correct": false}]', 'B', 1, 'easy', '["OPPOSITION TO BRITISH RULE IN KARNATAKA AND WODEYARS OF MYSORE"]', '["history", "karnataka", "rayanna"]', true),
  (sid, soc_id, 'mcq', 'The result of the Battle of Porto Novo in 1781 was that', '[{"key": "A", "value": "Hyder Ali was defeated by the British", "correct": true}, {"key": "B", "value": "Tipu Sultan was defeated by the British", "correct": false}, {"key": "C", "value": "Kittur was defeated by the British", "correct": false}, {"key": "D", "value": "Dondiya Wagh was martyred", "correct": false}]', 'A', 1, 'hard', '["OPPOSITION TO BRITISH RULE IN KARNATAKA AND WODEYARS OF MYSORE"]', '["history", "karnataka", "hyder_ali"]', true),
  (sid, soc_id, 'mcq', 'The King of Mysore who constructed the Bangalore-Mysore railway line was', '[{"key": "A", "value": "Jayachamaraja Wodeyar", "correct": false}, {"key": "B", "value": "Krishnaraja Wodeyar IV", "correct": false}, {"key": "C", "value": "Chamarajendra Wodeyar X", "correct": true}, {"key": "D", "value": "Raja Wodeyar", "correct": false}]', 'C', 1, 'hard', '["OPPOSITION TO BRITISH RULE IN KARNATAKA AND WODEYARS OF MYSORE"]', '["history", "karnataka", "mysore_kings"]', true),
  (sid, soc_id, 'mcq', 'The King of Mysore who was called ''Rajshri'' by Mahatma Gandhi was', '[{"key": "A", "value": "Jayachamaraja Wodeyar", "correct": false}, {"key": "B", "value": "Krishnaraja Wodeyar IV", "correct": true}, {"key": "C", "value": "Chamarajendra Wodeyar X", "correct": false}, {"key": "D", "value": "Raja Wodeyar", "correct": false}]', 'B', 1, 'medium', '["OPPOSITION TO BRITISH RULE IN KARNATAKA AND WODEYARS OF MYSORE"]', '["history", "karnataka", "mysore_kings"]', true),
  (sid, soc_id, 'mcq', 'The Navratri festival (Dasara) of Mysore was started in Srirangapattana by', '[{"key": "A", "value": "Jayachamaraja Wodeyar", "correct": false}, {"key": "B", "value": "Krishnaraja Wodeyar IV", "correct": false}, {"key": "C", "value": "Chamarajendra Wodeyar X", "correct": false}, {"key": "D", "value": "Raja Wodeyar", "correct": true}]', 'D', 1, 'easy', '["OPPOSITION TO BRITISH RULE IN KARNATAKA AND WODEYARS OF MYSORE"]', '["history", "karnataka", "dasara"]', true),
  (sid, soc_id, 'mcq', 'The state anthem of Mysore state during the rule of Wodeyars was', '[{"key": "A", "value": "Kayo Sri Gowri", "correct": true}, {"key": "B", "value": "Udayavagali Namma Cheluva Kannada Nadu", "correct": false}, {"key": "C", "value": "Palisemmanu Chamundeshwari", "correct": false}, {"key": "D", "value": "Jai Bharatha Jananiya Thanujathe", "correct": false}]', 'A', 1, 'easy', '["OPPOSITION TO BRITISH RULE IN KARNATAKA AND WODEYARS OF MYSORE"]', '["history", "karnataka", "anthem"]', true),
  (sid, soc_id, 'mcq', 'The Queen of Hadinadu gave her daughter in marriage to Yaduraya because', '[{"key": "A", "value": "Maranayaka ordered the Queen to do so", "correct": false}, {"key": "B", "value": "Yaduraya was handsome and the princess fell in love with him", "correct": false}, {"key": "C", "value": "Chamaraja pleaded the Queen to give her daughter in marriage to Yaduraya", "correct": false}, {"key": "D", "value": "Yaduraya killed Maranayaka and helped the Queen", "correct": true}]', 'D', 1, 'hard', '["OPPOSITION TO BRITISH RULE IN KARNATAKA AND WODEYARS OF MYSORE"]', '["history", "karnataka", "dynasty"]', true),
  (sid, soc_id, 'mcq', 'The social reform organization based on the principle of ''service to mankind is service to God'' is', '[{"key": "A", "value": "Satya Shodhak Samaj", "correct": false}, {"key": "B", "value": "Prarthana Samaj", "correct": false}, {"key": "C", "value": "Arya Samaj", "correct": false}, {"key": "D", "value": "Ramakrishna Mission", "correct": true}]', 'D', 1, 'medium', '["SOCIAL AND RELIGIOUS REFORM MOVEMENTS"]', '["history", "reforms", "ramakrishna_mission"]', true),
  (sid, soc_id, 'mcq', 'The newspaper started by Raja Ram Mohan Roy in Bengali to fight social evils was', '[{"key": "A", "value": "Samvada Kaumudi", "correct": true}, {"key": "B", "value": "Mooka Nayaka", "correct": false}, {"key": "C", "value": "Young India", "correct": false}, {"key": "D", "value": "Common Wheal", "correct": false}]', 'A', 1, 'easy', '["SOCIAL AND RELIGIOUS REFORM MOVEMENTS"]', '["history", "reforms", "brahmo_samaj"]', true),
  (sid, soc_id, 'mcq', 'The ''Purification Ritual'' (Shuddhi Movement) was the main activity of the', '[{"key": "A", "value": "Prarthana Samaj", "correct": false}, {"key": "B", "value": "Brahmo Samaj", "correct": false}, {"key": "C", "value": "Satyashodak Samaj", "correct": false}, {"key": "D", "value": "Arya Samaj", "correct": true}]', 'D', 1, 'medium', '["SOCIAL AND RELIGIOUS REFORM MOVEMENTS"]', '["history", "reforms", "shuddhi_movement"]', true),
  (sid, soc_id, 'mcq', 'The Theosophical Society was founded in New York by', '[{"key": "A", "value": "Raja Ram Mohan Roy", "correct": false}, {"key": "B", "value": "Dayananda Saraswati", "correct": false}, {"key": "C", "value": "Annie Besant", "correct": false}, {"key": "D", "value": "Colonel H.S. Olcott and Madam Blavatsky", "correct": true}]', 'D', 1, 'medium', '["SOCIAL AND RELIGIOUS REFORM MOVEMENTS"]', '["history", "reforms", "theosophical_society"]', true),
  (sid, soc_id, 'mcq', 'The weekly newspaper ''New India'' was started by', '[{"key": "A", "value": "Raja Ram Mohan Roy", "correct": false}, {"key": "B", "value": "Mahatma Gandhi", "correct": false}, {"key": "C", "value": "Annie Besant", "correct": true}, {"key": "D", "value": "Dayananda Saraswati", "correct": false}]', 'C', 1, 'medium', '["SOCIAL AND RELIGIOUS REFORM MOVEMENTS"]', '["history", "reforms", "annie_besant"]', true),
  (sid, soc_id, 'mcq', 'The famous call ''Back to the Vedas'' was given by', '[{"key": "A", "value": "Dayananda Saraswati", "correct": true}, {"key": "B", "value": "Mahatma Gandhi", "correct": false}, {"key": "C", "value": "Swami Vivekananda", "correct": false}, {"key": "D", "value": "Raja Ram Mohan Roy", "correct": false}]', 'A', 1, 'easy', '["SOCIAL AND RELIGIOUS REFORM MOVEMENTS"]', '["history", "reforms", "arya_samaj"]', true),
  (sid, soc_id, 'mcq', 'The organisation which advocated free and compulsory education to bring social reforms was', '[{"key": "A", "value": "Prarthana Samaj", "correct": false}, {"key": "B", "value": "Brahmo Samaj", "correct": false}, {"key": "C", "value": "Satyashodak Samaj", "correct": true}, {"key": "D", "value": "Arya Samaj", "correct": false}]', 'C', 1, 'medium', '["SOCIAL AND RELIGIOUS REFORM MOVEMENTS"]', '["history", "reforms", "satyashodhak_samaj"]', true),
  (sid, soc_id, 'mcq', 'The leader who rose in revolt against the British in Kanpur in 1857 was', '[{"key": "A", "value": "Mangal Pandey", "correct": false}, {"key": "B", "value": "Dondiya Wagh", "correct": false}, {"key": "C", "value": "Nana Saheb", "correct": true}, {"key": "D", "value": "Bahadur Shah II", "correct": false}]', 'C', 1, 'medium', '["THE FIRST WAR OF INDIAN INDEPENDENCE (1857)"]', '["history", "1857_revolt", "kanpur"]', true),
  (sid, soc_id, 'mcq', 'One of the major reasons for the failure of the First Indian War of Independence was that', '[{"key": "A", "value": "It was spread across the country", "correct": false}, {"key": "B", "value": "It was a well-organized rebellion", "correct": false}, {"key": "C", "value": "It did not have a strong common leader", "correct": true}, {"key": "D", "value": "Many Indian kings were disloyal to the British", "correct": false}]', 'C', 1, 'medium', '["THE FIRST WAR OF INDIAN INDEPENDENCE (1857)"]', '["history", "1857_revolt", "failures"]', true),
  (sid, soc_id, 'mcq', 'During the 1857 revolt, the sepoys lost the trust of the common people because of', '[{"key": "A", "value": "Lack of support from the native kings", "correct": false}, {"key": "B", "value": "Lack of appropriate guidance", "correct": false}, {"key": "C", "value": "Self-interest and struggle for individual rights", "correct": false}, {"key": "D", "value": "Looting and robberies committed by the soldiers", "correct": true}]', 'D', 1, 'hard', '["THE FIRST WAR OF INDIAN INDEPENDENCE (1857)"]', '["history", "1857_revolt", "failures"]', true),
  (sid, soc_id, 'mcq', 'The founder of the Indian National Congress (INC) in 1885 was', '[{"key": "A", "value": "Mahatma Gandhiji", "correct": false}, {"key": "B", "value": "A.O. Hume", "correct": true}, {"key": "C", "value": "Bal Gangadhar Tilak", "correct": false}, {"key": "D", "value": "Gopalakrishna Gokhale", "correct": false}]', 'B', 1, 'easy', '["THE FREEDOM STRUGGLE"]', '["history", "freedom_struggle", "inc"]', true),
  (sid, soc_id, 'mcq', 'The English newspaper ''Maratha'' was started during the freedom struggle by', '[{"key": "A", "value": "Jawaharlal Nehru", "correct": false}, {"key": "B", "value": "Ras Bihari Bose", "correct": false}, {"key": "C", "value": "Bal Gangadhar Tilak", "correct": true}, {"key": "D", "value": "Gopalakrishna Gokhale", "correct": false}]', 'C', 1, 'easy', '["THE FREEDOM STRUGGLE"]', '["history", "freedom_struggle", "tilak"]', true),
  (sid, soc_id, 'mcq', 'The Swarajya Party was established by Motilal Nehru and C.R. Das in the year', '[{"key": "A", "value": "1924", "correct": false}, {"key": "B", "value": "1923", "correct": true}, {"key": "C", "value": "1929", "correct": false}, {"key": "D", "value": "1906", "correct": false}]', 'B', 1, 'hard', '["THE FREEDOM STRUGGLE"]', '["history", "freedom_struggle", "swarajya_party"]', true),
  (sid, soc_id, 'mcq', 'The Haripura session of the Indian National Congress was presided over by', '[{"key": "A", "value": "Jawaharlal Nehru", "correct": false}, {"key": "B", "value": "Dr. B.R. Ambedkar", "correct": false}, {"key": "C", "value": "Lala Lajpat Rai", "correct": false}, {"key": "D", "value": "Subhash Chandra Bose", "correct": true}]', 'D', 1, 'medium', '["THE FREEDOM STRUGGLE"]', '["history", "freedom_struggle", "sessions"]', true),
  (sid, soc_id, 'mcq', 'The ''Drain Theory'' of wealth from India to England was propagated by', '[{"key": "A", "value": "Dadabhai Naoroji", "correct": true}, {"key": "B", "value": "Aurobindo Ghosh", "correct": false}, {"key": "C", "value": "Lala Lajpat Rai", "correct": false}, {"key": "D", "value": "Subhash Chandra Bose", "correct": false}]', 'A', 1, 'easy', '["THE FREEDOM STRUGGLE"]', '["history", "freedom_struggle", "economics"]', true),
  (sid, soc_id, 'mcq', 'The first Prime Minister of independent India was', '[{"key": "A", "value": "Jawaharlal Nehru", "correct": true}, {"key": "B", "value": "Dr. B.R. Ambedkar", "correct": false}, {"key": "C", "value": "Lala Lajpat Rai", "correct": false}, {"key": "D", "value": "Subhash Chandra Bose", "correct": false}]', 'A', 1, 'easy', '["THE FREEDOM STRUGGLE"]', '["history", "freedom_struggle", "leaders"]', true),
  (sid, soc_id, 'mcq', 'Which of the following was a prominent moderate leader of the Indian National Congress?', '[{"key": "A", "value": "Bipin Chandra Pal", "correct": false}, {"key": "B", "value": "Lala Lajpat Rai", "correct": false}, {"key": "C", "value": "Gopalakrishna Gokhale", "correct": true}, {"key": "D", "value": "Bal Gangadhar Tilak", "correct": false}]', 'C', 1, 'hard', '["THE FREEDOM STRUGGLE"]', '["history", "freedom_struggle", "moderates"]', true),
  (sid, soc_id, 'mcq', 'The real reason behind the partition of Bengal by the British in 1905 was', '[{"key": "A", "value": "To unite Hindus and Muslims", "correct": false}, {"key": "B", "value": "To promote trade in Bengal", "correct": false}, {"key": "C", "value": "To develop the Bengal region", "correct": false}, {"key": "D", "value": "To suppress the nationalistic struggle against the British", "correct": true}]', 'D', 1, 'hard', '["THE FREEDOM STRUGGLE"]', '["history", "freedom_struggle", "partition_of_bengal"]', true),
  (sid, soc_id, 'mcq', 'The Quit India Movement gave leadership to non-Congress socialist leaders, most prominent among them being', '[{"key": "A", "value": "Kasturba Gandhi", "correct": false}, {"key": "B", "value": "Dr. B.R. Ambedkar", "correct": false}, {"key": "C", "value": "Jayaprakash Narayan", "correct": true}, {"key": "D", "value": "Maulana Abul Kalam Azad", "correct": false}]', 'C', 1, 'hard', '["THE FREEDOM STRUGGLE"]', '["history", "freedom_struggle", "quit_india"]', true),
